    async function renderHealth(params){
        loading('Cargando sanidad…');
        const filters={from:params.get('from')||'',to:params.get('to')||'',type:params.get('type')||'',category_id:params.get('category_id')||''};
        const data=await api('livestock_health_dashboard',{params:filters});const summary=data.summary||{};const attachments=data.attachments||[];
        const controlCards=(rows=[],tone='upcoming')=>rows.length?`<div class="health-control-list">${rows.map(r=>`<a href="#/vaca/${r.cattle_id}" class="health-control-card ${tone}"><time>${formatDate(r.next_date)}</time><div><strong>Caravana ${h(r.tag_number)}</strong><small>${h(healthTypeLabel(r.record_type))} · ${h(r.category_name)}</small><p>${h(r.description)}</p></div></a>`).join('')}</div>`:'<p class="muted empty-line">No hay controles en este grupo.</p>';
        shell({title:'Sanidad',subtitle:'Un lugar claro para registrar tratamientos, adjuntar fotos y controlar vencimientos',active:'health',content:`
            <section class="health-summary-grid health-summary-clean"><div><span>Registros totales</span><strong>${Number(summary.total||0)}</strong><small>Historial sanitario</small></div><div><span>Últimos 30 días</span><strong>${Number(summary.last30||0)}</strong><small>Aplicaciones recientes</small></div><div class="${Number(summary.overdue||0)>0?'negative':''}"><span>Controles vencidos</span><strong>${Number(summary.overdue||0)}</strong><small>Necesitan atención</small></div><div><span>Próximos 30 días</span><strong>${Number(summary.upcoming||0)}</strong><small>Controles programados</small></div></section>
            <section class="health-attention-grid">
                <article class="panel health-attention-panel overdue"><div class="health-attention-title"><span>!</span><div><h2>Controles vencidos</h2><p>Lo que debería haberse revisado.</p></div></div>${controlCards(data.overdue||[],'overdue')}</article>
                <article class="panel health-attention-panel upcoming"><div class="health-attention-title"><span>⌁</span><div><h2>Próximos controles</h2><p>Lo programado para los próximos 30 días.</p></div></div>${controlCards(data.upcoming||[],'upcoming')}</article>
            </section>
            <section class="health-entry-layout">
                <article class="form-card health-entry-card"><div class="panel-header"><div><h2>Registrar una aplicación sanitaria</h2><p>Puede aplicarla a una categoría, a animales elegidos o a todo el rodeo activo.</p></div></div>
                    <form data-form="livestock-health-batch-save" enctype="multipart/form-data">
                        <div class="health-form-step"><div class="health-step-number">1</div><div class="health-step-content"><h3>¿A qué animales se aplica?</h3><div class="health-target-grid"><label class="field"><span>Forma de selección</span><select name="scope" data-health-scope><option value="category">Una categoría completa</option><option value="selected">Elegir animales</option><option value="all">Todos los animales activos</option></select></label><div data-health-category><label class="field"><span>Categoría</span><select name="category_id"><option value="">Seleccione</option>${(data.categories||[]).map(c=>`<option value="${c.id}">${h(c.name)}</option>`).join('')}</select></label></div></div><div class="health-selected-area" data-health-selected hidden><span class="field-caption">Marque los animales</span><div class="selection-grid compact-selection">${(data.cattle||[]).map(c=>`<label class="animal-selection-card"><input type="checkbox" name="cattle_ids[]" value="${c.id}"><span class="selection-check">✓</span><strong>Caravana ${h(c.tag_number)}</strong><small>${h(c.category_name)} · ${h(c.parcel_name||'Sin parcela')}</small></label>`).join('')}</div></div></div></div>
                        <div class="health-form-step"><div class="health-step-number">2</div><div class="health-step-content"><h3>¿Qué se realizó?</h3><div class="form-grid two-columns"><label class="field"><span>Fecha</span><input type="date" name="record_date" value="${today()}" required></label><label class="field"><span>Tipo</span><select name="record_type">${(data.health_types||Object.keys(healthLabels)).map(v=>`<option value="${v}">${h(healthTypeLabel(v))}</option>`).join('')}</select></label><label class="field full"><span>Descripción *</span><textarea name="description" rows="4" required placeholder="Ej.: vacunación preventiva, revisión por renguera, tratamiento de herida…"></textarea></label><label class="field"><span>Producto</span><input name="product" placeholder="Nombre o marca"></label><label class="field"><span>Dosis</span><input name="dose" placeholder="Ej.: 5 ml"></label><label class="field"><span>Profesional o responsable</span><input name="professional"></label><label class="field"><span>Próximo control</span><input type="date" name="next_date"></label></div></div></div>
                        <div class="health-form-step health-file-step"><div class="health-step-number">3</div><div class="health-step-content"><h3>Fotos del producto o procedimiento</h3><p>Puede sacar o elegir varias fotos. También admite PDF.</p><label class="health-file-drop"><input type="file" name="health_files[]" accept="image/jpeg,image/png,image/webp,application/pdf" multiple><span>＋</span><strong>Agregar fotos o archivos</strong><small>JPG, PNG, WEBP o PDF</small></label><label class="field"><span>Descripción de los archivos</span><input name="file_caption" placeholder="Ej.: frasco, lote y vencimiento del producto"></label></div></div>
                        <div class="health-submit-bar"><div><strong>Al guardar</strong><small>El registro aparecerá automáticamente en la ficha de cada animal alcanzado.</small></div><button class="btn btn-primary btn-large">Guardar aplicación sanitaria</button></div>
                    </form>
                </article>
                <aside class="panel health-help-card"><div class="health-help-icon">✚</div><h2>Cómo usar esta sección</h2><ol><li>Elija a qué animales corresponde.</li><li>Registre qué se hizo y cuándo.</li><li>Adjunte fotos del producto, número de lote o procedimiento.</li><li>Use “Próximo control” para generar el aviso automático.</li></ol><p>También puede agregar un registro directamente desde la ficha de una vaca.</p></aside>
            </section>
            <section class="panel health-history-panel"><div class="panel-header"><div><h2>Historial sanitario</h2><p>Cada tarjeta muestra claramente el animal, el tratamiento, el próximo control y sus fotos.</p></div></div>
                <form class="filter-panel health-filter" data-form="livestock-health-filter"><label class="field"><span>Desde</span><input type="date" name="from" value="${h(filters.from)}"></label><label class="field"><span>Hasta</span><input type="date" name="to" value="${h(filters.to)}"></label><label class="field"><span>Tipo</span><select name="type"><option value="">Todos</option>${(data.health_types||Object.keys(healthLabels)).map(v=>`<option value="${v}" ${filters.type===v?'selected':''}>${h(healthTypeLabel(v))}</option>`).join('')}</select></label><label class="field"><span>Categoría</span><select name="category_id"><option value="">Todas</option>${(data.categories||[]).map(c=>`<option value="${c.id}" ${String(filters.category_id)===String(c.id)?'selected':''}>${h(c.name)}</option>`).join('')}</select></label><div class="filter-actions"><button class="btn btn-secondary">Aplicar filtros</button><a class="btn btn-ghost" href="#/sanidad-ganadera">Limpiar</a></div></form>
                ${(data.records||[]).length?`<div class="health-history-cards">${data.records.map(r=>`<article class="health-history-card"><header><div class="health-record-type type-${h(r.record_type)}">${h(healthTypeLabel(r.record_type))}</div><div><strong>Caravana ${h(r.tag_number)}</strong><small>${categoryPill(r.category_name,r.category_color)} ${r.scope_label?`<span class="health-scope-pill">${h(r.scope_label)}</span>`:''}</small></div><time>${formatDate(r.record_date)}</time></header><div class="health-history-body"><div class="health-main-detail"><h3>${h(r.description)}</h3><div class="health-detail-chips">${r.product?`<span><b>Producto</b>${h(r.product)}</span>`:''}${r.dose?`<span><b>Dosis</b>${h(r.dose)}</span>`:''}${r.professional?`<span><b>Responsable</b>${h(r.professional)}</span>`:''}<span class="${r.next_date&&String(r.next_date)<today()?'overdue':''}"><b>Próximo control</b>${formatDate(r.next_date)}</span></div></div>${healthEvidence(r,attachments,true)}</div></article>`).join('')}</div>`:'<p class="muted empty-line">No hay registros sanitarios para los filtros seleccionados.</p>'}
            </section>
            ${(data.batches||[]).length?`<section class="panel health-batches-panel"><details><summary><div><strong>Aplicaciones grupales</strong><small>Auditoría de los tratamientos aplicados en conjunto</small></div><span>${data.batches.length}</span></summary><div class="batch-list">${data.batches.map(b=>`<article><div class="health-record-type type-${h(b.record_type)}">${h(healthTypeLabel(b.record_type))}</div><div><strong>${formatDate(b.record_date)} · ${h(b.description)}</strong><small>${h(b.scope_label||b.category_name||'Selección')} · ${Number(b.animal_count)} animales${Number(b.attachment_count||0)?` · ${Number(b.attachment_count)} archivo(s)`:''}</small></div></article>`).join('')}</div></details></section>`:''}`});
        const scope=document.querySelector('[data-health-scope]');const sync=()=>{document.querySelector('[data-health-category]')?.toggleAttribute('hidden',scope?.value!=='category');document.querySelector('[data-health-selected]')?.toggleAttribute('hidden',scope?.value!=='selected');};scope?.addEventListener('change',sync);sync();hydrateProtectedImages();
    }

    function initHealthScope(){const select=document.querySelector('[data-health-scope]');const category=document.querySelector('[data-health-category]');const selected=document.querySelector('[data-health-selected]');if(!select)return;const update=()=>{category.hidden=select.value!=='category';selected.hidden=select.value!=='selected';};select.addEventListener('change',update);update();}

